import json
from fractions import Fraction as F
from math import isqrt

# For x in [n, n+1): g(x) = n^2 - x, which takes values in (n^2-n-1, n^2-n].
ks = sorted({n*n - n for n in range(-60, 61)})
# k = n(n-1) = m(m+1) with m = n-1 (n>=1) or m = -n (n<=0): check form and coverage
def is_pronic(k):
    m = isqrt(k)
    return m*(m+1) == k
all_pronic = all(is_pronic(k) for k in ks)
small = [k for k in ks if k <= 3000]
expected = [m*(m+1) for m in range(0, 60) if m*(m+1) <= 3000]
coverage_ok = small == expected

# Independent membership check on a rational grid
def in_range_bruteforce(y):
    for n in range(-80, 81):
        if n*n - n - 1 < y <= n*n - n:
            return True
    return False

def in_range_formula(y):
    import math
    k = math.ceil(y)
    return k >= 0 and is_pronic(k)

grid_ok = True
for num in range(-40, 400):
    y = F(num, 4)
    if in_range_bruteforce(y) != in_range_formula(y):
        grid_ok = False
        break

if all_pronic and coverage_ok and grid_ok:
    first = [f"({k-1}, {k}]" for k in expected[:5]]
    answer = ("Union over integers m>=0 of (m^2+m-1, m^2+m]: "
              + " U ".join(first) + " U ...")
    print(json.dumps({
        "final_answer": answer,
        "evidence": {
            "interval_endpoints_k": expected[:8],
            "all_k_are_m(m+1)": all_pronic,
            "coverage_ok": coverage_ok,
            "grid_check_ok": grid_ok,
        }
    }))
else:
    print("UNSUPPORTED")
